"""
Metric plotting utilities for training visualization.

This module provides functions to visualize training metrics from CSV files
generated by PyTorch Lightning's CSVLogger.
"""

from typing import Tuple, Optional, List, Dict
import os
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from matplotlib.figure import Figure
from matplotlib.axes import Axes


# Metric display names: Only basic/essential metrics with explicit display names
# All other metrics will be auto-generated from their column names
METRIC_DISPLAY_NAMES = {
  "loss_epoch": ("Loss", "Loss"),
  "accuracy": ("Accuracy", "Accuracy"),
}

# Priority order for metrics (shown first in plots)
# Only basic metrics; all others sorted alphabetically after these
METRIC_PRIORITY = [
  "loss_epoch",
  "accuracy",
  "f1score",
  "kappa",
]


def _validate_file_path(csv_path: str) -> None:
  """Check file existence and extension."""
  if not os.path.exists(csv_path):
    raise FileNotFoundError(f"Metrics file not found: {csv_path}")
  if not csv_path.endswith(".csv"):
    raise ValueError(f"File must be a CSV: {csv_path}")


def _load_and_preprocess_data(csv_path: str) -> pd.DataFrame:
  """
  Load CSV and return full dataframe.

  Args:
      csv_path: Path to the metrics CSV file

  Returns:
      Full dataframe with all metrics
  """
  df = pd.read_csv(csv_path)

  # Validate required columns exist
  required_cols = ["epoch", "step"]
  missing = [col for col in required_cols if col not in df.columns]
  if missing:
    raise ValueError(f"Missing required columns: {missing}")

  return df


def _prepare_training_data(df: pd.DataFrame) -> pd.DataFrame:
  """
  Extract training metrics at epoch level.

  Auto-detects all columns with 'train_' prefix while keeping basic columns explicit.

  Filter: rows where 'epoch' is not NaN and 'train_accuracy' is not NaN

  Args:
      df: Full metrics dataframe

  Returns:
      DataFrame with epoch-level training metrics
  """
  # Filter to rows with epoch-level training metrics
  train_df = df[df["train_accuracy"].notna()].copy()

  # Define basic required columns (explicit)
  basic_train_cols = ["epoch", "train_loss_epoch", "train_accuracy"]

  # Auto-detect additional train_* columns
  auto_detected = [
    col for col in df.columns if col.startswith("train_") and col not in basic_train_cols
  ]

  # Combine: basic + auto-detected
  train_cols = basic_train_cols + auto_detected

  # Only include columns that exist
  available_cols = [col for col in train_cols if col in train_df.columns]

  return train_df[available_cols]


def _prepare_validation_data(df: pd.DataFrame) -> pd.DataFrame:
  """
  Extract validation metrics.

  Auto-detects all columns with 'val_' prefix while keeping basic columns explicit.

  Filter: rows where 'val_accuracy' is not NaN

  Args:
      df: Full metrics dataframe

  Returns:
      DataFrame with validation metrics
  """
  # Filter to rows with validation metrics
  val_df = df[df["val_accuracy"].notna()].copy()

  # Define basic required columns (explicit)
  basic_val_cols = ["epoch", "val_loss", "val_accuracy"]

  # Auto-detect additional val_* columns
  auto_detected = [
    col for col in df.columns if col.startswith("val_") and col not in basic_val_cols
  ]

  # Combine: basic + auto-detected
  val_cols = basic_val_cols + auto_detected

  # Only include columns that exist
  available_cols = [col for col in val_cols if col in val_df.columns]

  return val_df[available_cols]


def _generate_metric_pairs(train_df: pd.DataFrame, val_df: pd.DataFrame) -> List[Dict]:
  """
  Auto-generate train/val metric pairs from dataframe columns.

  Pairs train_* columns with corresponding val_* columns and generates
  display metadata for each pair.

  Args:
      train_df: Training data with train_* columns
      val_df: Validation data with val_* columns

  Returns:
      List of dicts with keys: train_col, val_col, metric_name, title, ylabel
      Sorted by priority order
  """
  pairs = []

  # Get all train columns (excluding 'epoch')
  train_cols = [col for col in train_df.columns if col.startswith("train_") and col != "train_"]

  for train_col in train_cols:
    # Extract base metric name (remove 'train_' prefix)
    metric_name = train_col.replace("train_", "")

    # Construct corresponding val column name
    # Handle special case: train_loss_epoch -> val_loss
    if metric_name == "loss_epoch":
      val_col = "val_loss"
      metric_key = "loss_epoch"
    else:
      val_col = f"val_{metric_name}"
      metric_key = metric_name

    # Only pair if validation column exists
    if val_col in val_df.columns:
      # Get display names
      if metric_key in METRIC_DISPLAY_NAMES:
        title_base, ylabel = METRIC_DISPLAY_NAMES[metric_key]
      else:
        # Generate from metric name (title case, replace underscores)
        title_base = metric_name.replace("_", " ").title()
        ylabel = title_base

      # Create full title
      title = f"Training and Validation {title_base}"

      pairs.append(
        {
          "train_col": train_col,
          "val_col": val_col,
          "metric_name": metric_key,
          "title": title,
          "ylabel": ylabel,
        }
      )

  # Sort by priority order
  def sort_key(pair):
    metric = pair["metric_name"]
    if metric in METRIC_PRIORITY:
      return (0, METRIC_PRIORITY.index(metric))
    else:
      return (1, metric)  # Unknown metrics sorted alphabetically after priority

  pairs.sort(key=sort_key)

  return pairs


def _create_metric_subplot(
  ax: Axes,
  train_df: pd.DataFrame,
  val_df: pd.DataFrame,
  train_col: str,
  val_col: str,
  title: str,
  ylabel: str,
) -> None:
  """
  Create a single metric subplot with training and validation curves.

  Args:
      ax: Matplotlib axes object
      train_df: Training data
      val_df: Validation data
      train_col: Training column name
      val_col: Validation column name
      title: Subplot title
      ylabel: Y-axis label
  """
  # Check if data is available
  has_train = train_col in train_df.columns and train_df[train_col].notna().any()
  has_val = val_col in val_df.columns and val_df[val_col].notna().any()

  if not has_train and not has_val:
    ax.text(
      0.5,
      0.5,
      "No data available",
      ha="center",
      va="center",
      fontsize=12,
      transform=ax.transAxes,
    )
    ax.set_title(title, fontsize=14, fontweight="bold")
    return

  # Plot training data
  if has_train:
    train_clean = train_df[["epoch", train_col]].dropna()
    ax.plot(
      train_clean["epoch"],
      train_clean[train_col],
      color="tab:blue",
      linewidth=2.0,
      label="Train",
      alpha=0.9,
    )

  # Plot validation data
  if has_val:
    val_clean = val_df[["epoch", val_col]].dropna()
    ax.plot(
      val_clean["epoch"],
      val_clean[val_col],
      color="tab:orange",
      linewidth=2.0,
      label="Validation",
      alpha=0.9,
    )

  # Styling
  ax.set_title(title, fontsize=14, fontweight="bold")
  ax.set_xlabel("Epoch", fontsize=12)
  ax.set_ylabel(ylabel, fontsize=12)
  ax.legend(fontsize=11, frameon=True, shadow=True)
  ax.grid(True, linestyle="--", alpha=0.3)
  ax.tick_params(labelsize=10)


def _plot_training_validation_curves(
  train_df: pd.DataFrame, val_df: pd.DataFrame
) -> Tuple[Figure, np.ndarray]:
  """
  Create 2x2 grid of training and validation curves.

  Automatically detects and plots the top 4 priority metrics.

  Args:
      train_df: Training data
      val_df: Validation data

  Returns:
      Tuple of (figure, axes)
  """
  # Set seaborn style
  sns.set_style("whitegrid")

  # Create figure with 2x2 subplots
  fig, axes = plt.subplots(2, 2, figsize=(16, 12))

  # Generate metric pairs dynamically
  metric_pairs = _generate_metric_pairs(train_df, val_df)

  # Get top 4 metrics for 2x2 grid
  top_metrics = metric_pairs[:4]

  # Plot each metric dynamically
  positions = [(0, 0), (0, 1), (1, 0), (1, 1)]
  for i, (pos, pair) in enumerate(zip(positions, top_metrics)):
    _create_metric_subplot(
      axes[pos[0], pos[1]],
      train_df,
      val_df,
      pair["train_col"],
      pair["val_col"],
      pair["title"],
      pair["ylabel"],
    )

  # Fill remaining subplots with "No data" if less than 4 metrics
  for i in range(len(top_metrics), 4):
    pos = positions[i]
    axes[pos[0], pos[1]].text(
      0.5,
      0.5,
      "No additional metrics",
      ha="center",
      va="center",
      fontsize=12,
      transform=axes[pos[0], pos[1]].transAxes,
    )
    axes[pos[0], pos[1]].set_title("", fontsize=14, fontweight="bold")

  # Adjust layout
  plt.tight_layout()

  return fig, axes


def _plot_comprehensive_dashboard(
  train_df: pd.DataFrame, val_df: pd.DataFrame
) -> Tuple[Figure, np.ndarray]:
  """
  Create 3x3 grid comprehensive dashboard with all metrics.

  Automatically detects and plots up to 9 priority metrics.

  Args:
      train_df: Training data
      val_df: Validation data

  Returns:
      Tuple of (figure, axes)
  """
  # Set seaborn style
  sns.set_style("whitegrid")

  # Create figure with 3x3 subplots
  fig, axes = plt.subplots(3, 3, figsize=(24, 18))

  # Generate metric pairs dynamically
  metric_pairs = _generate_metric_pairs(train_df, val_df)

  # Get top 9 metrics for 3x3 grid
  top_metrics = metric_pairs[:9]

  # Plot each metric dynamically
  positions = [
    (0, 0),
    (0, 1),
    (0, 2),
    (1, 0),
    (1, 1),
    (1, 2),
    (2, 0),
    (2, 1),
    (2, 2),
  ]

  for i, (pos, pair) in enumerate(zip(positions, top_metrics)):
    _create_metric_subplot(
      axes[pos[0], pos[1]],
      train_df,
      val_df,
      pair["train_col"],
      pair["val_col"],
      pair["title"],
      pair["ylabel"],
    )

  # Fill remaining subplots with "No data" if less than 9 metrics
  for i in range(len(top_metrics), 9):
    pos = positions[i]
    axes[pos[0], pos[1]].text(
      0.5,
      0.5,
      "No additional metrics",
      ha="center",
      va="center",
      fontsize=12,
      transform=axes[pos[0], pos[1]].transAxes,
    )
    axes[pos[0], pos[1]].set_title("", fontsize=14, fontweight="bold")

  # Adjust layout
  plt.tight_layout()

  return fig, axes


def plot_metrics_from_csv(
  metrics_csv_path: str, output_dir: Optional[str] = None, dpi: int = 300
) -> Tuple[str, str]:
  """
  Generate training visualizations from a metrics CSV file.

  Creates two visualization files:
  1. training_validation_curves.png - 2x2 grid with main metrics
  2. comprehensive_dashboard.png - 3x3 grid with all metrics including loss components

  Args:
      metrics_csv_path: Path to the metrics.csv file generated by PyTorch Lightning
      output_dir: Output directory for plots. If None, creates 'metric_plot'
                 subdirectory in the same location as the CSV file
      dpi: Resolution for saved figures (default: 300)

  Returns:
      Tuple of (training_curves_path, dashboard_path)

  Raises:
      FileNotFoundError: If the CSV file doesn't exist
      ValueError: If the CSV file is invalid or missing required columns

  Example:
      >>> curves, dashboard = plot_metrics_from_csv('logs/version_1/metrics.csv')
      >>> print(f"Plots saved to: {os.path.dirname(curves)}")
  """
  # Validate input file
  _validate_file_path(metrics_csv_path)

  # Set up output directory
  if output_dir is None:
    output_dir = os.path.join(os.path.dirname(metrics_csv_path), "metric_plot")

  os.makedirs(output_dir, exist_ok=True)

  # Load and preprocess data
  print(f"Loading metrics from: {metrics_csv_path}")
  df = _load_and_preprocess_data(metrics_csv_path)

  # Prepare training and validation data
  train_df = _prepare_training_data(df)
  val_df = _prepare_validation_data(df)

  if len(train_df) == 0 and len(val_df) == 0:
    raise ValueError("No training or validation data found in metrics CSV")

  print(f"Found {len(train_df)} training epochs and {len(val_df)} validation epochs")

  # Generate training & validation curves plot
  print("Generating training and validation curves...")
  fig1, _ = _plot_training_validation_curves(train_df, val_df)
  curves_path = os.path.join(output_dir, "training_validation_curves.png")
  fig1.savefig(curves_path, dpi=dpi, bbox_inches="tight")
  plt.close(fig1)
  print(f"Saved: {curves_path}")

  # Generate comprehensive dashboard
  print("Generating comprehensive dashboard...")
  fig2, _ = _plot_comprehensive_dashboard(train_df, val_df)
  dashboard_path = os.path.join(output_dir, "comprehensive_dashboard.png")
  fig2.savefig(dashboard_path, dpi=dpi, bbox_inches="tight")
  plt.close(fig2)
  print(f"Saved: {dashboard_path}")

  print(f"\nAll plots saved to: {output_dir}")

  return curves_path, dashboard_path


if __name__ == "__main__":
  import sys

  if len(sys.argv) > 1:
    csv_path = sys.argv[1]
    output = sys.argv[2] if len(sys.argv) > 2 else None

    try:
      curves, dashboard = plot_metrics_from_csv(csv_path, output)
      print("\nSuccess! Generated plots:")
      print(f"  - {curves}")
      print(f"  - {dashboard}")
    except Exception as e:
      print(f"Error: {e}", file=sys.stderr)
      sys.exit(1)
  else:
    print("Usage: python metric_plot.py <metrics_csv_path> [output_dir]")
    print("\nExample:")
    print("  python metric_plot.py logs/version_1/metrics.csv")
    print("  python metric_plot.py logs/version_1/metrics.csv ./plots")
    sys.exit(1)
